usage:
type SignUpValues = {
  email: string;
  age: number;
  acceptedTerms: boolean;
};

const SignUpForm = createForm<SignUpValues>();

function SignUp() {
  const form = SignUpForm.useForm({
    defaultValues: { email: '', age: 18, acceptedTerms: false },
    onSubmit: async (values) => register(values),
  });

  return (
    <SignUpForm form={form}>
      <SignUpForm.Field
        name="email"
        validate={(value) => (value.includes('@') ? undefined : 'Enter a valid email')}
      >
        {(field) => (
          <Input
            label="Email"
            value={field.value}
            onChangeText={field.onChange}
            onBlur={field.onBlur}
            errorMessage={field.error}
          />
        )}
      </SignUpForm.Field>
      <Button onPress={form.handleSubmit}>Create account</Button>
    </SignUpForm>
  );
}

